-- H2 reference DDL only. Integrate with the existing app's schema management.
-- GORM's auto-generated column naming and foreign keys may differ: choose ONE schema strategy.
CREATE TABLE IF NOT EXISTS pm_workspace (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 version BIGINT NOT NULL DEFAULT 0,
 name VARCHAR(160) NOT NULL,
 description CLOB,
 owner_id BIGINT NOT NULL,
 inventory_revision BIGINT NOT NULL DEFAULT 0,
 date_created TIMESTAMP,
 last_updated TIMESTAMP,
 CONSTRAINT pm_workspace_owner_name_uq UNIQUE (owner_id, name)
);
CREATE TABLE IF NOT EXISTS pm_workspace_member (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 version BIGINT NOT NULL DEFAULT 0,
 workspace_id BIGINT NOT NULL,
 user_id BIGINT NOT NULL,
 access_role VARCHAR(16) NOT NULL,
 date_created TIMESTAMP,
 last_updated TIMESTAMP,
 CONSTRAINT pm_workspace_member_uq UNIQUE (workspace_id, user_id),
 CONSTRAINT pm_workspace_member_fk FOREIGN KEY (workspace_id) REFERENCES pm_workspace(id)
);
CREATE TABLE IF NOT EXISTS pm_workspace_part (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 version BIGINT NOT NULL DEFAULT 0,
 workspace_id BIGINT NOT NULL,
 part_id BIGINT NOT NULL,
 file_name VARCHAR(512) NOT NULL,
 recorded_major INTEGER NOT NULL,
 recorded_minor INTEGER NOT NULL,
 date_created TIMESTAMP,
 last_updated TIMESTAMP,
 CONSTRAINT pm_workspace_part_uq UNIQUE (workspace_id, part_id),
 CONSTRAINT pm_workspace_part_fk FOREIGN KEY (workspace_id) REFERENCES pm_workspace(id)
);
CREATE INDEX IF NOT EXISTS pm_workspace_owner_idx ON pm_workspace(owner_id);
CREATE INDEX IF NOT EXISTS pm_workspace_member_workspace_idx ON pm_workspace_member(workspace_id);
CREATE INDEX IF NOT EXISTS pm_workspace_part_workspace_idx ON pm_workspace_part(workspace_id);
